import re, sys, zlib

def load(path):
    data = open(path, 'rb').read()
    return data

def objects(data):
    objs = {}
    for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj\b', data):
        start = m.end()
        end = data.find(b'endobj', start)
        if end == -1:
            continue
        objs[int(m.group(1))] = data[start:end]
    return objs

def stream_bytes(body):
    m = re.search(rb'stream\r?\n', body)
    if not m:
        return None
    start = m.end()
    end = body.rfind(b'endstream')
    raw = body[start:end]
    if raw.endswith(b'\n'):
        raw = raw[:-1]
    if raw.endswith(b'\r'):
        raw = raw[:-1]
    if b'FlateDecode' in body[:m.start()]:
        try:
            return zlib.decompress(raw)
        except Exception:
            try:
                return zlib.decompressobj().decompress(raw)
            except Exception:
                return None
    return raw

def unescape_pdf_literal(s):
    out = bytearray()
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == 0x5c and i+1 < n:
            d = s[i+1]
            mp = {0x6e:10,0x72:13,0x74:9,0x62:8,0x66:12,0x28:0x28,0x29:0x29,0x5c:0x5c}
            if d in mp:
                out.append(mp[d]); i += 2; continue
            if 0x30 <= d <= 0x37:
                j = i+1
                oct_str = bytearray()
                while j < n and len(oct_str) < 3 and 0x30 <= s[j] <= 0x37:
                    oct_str.append(s[j]); j += 1
                try:
                    out.append(int(oct_str, 8) & 0xFF)
                except Exception:
                    pass
                i = j; continue
            if d in (10, 13):
                i += 2; continue
            out.append(d); i += 2; continue
        out.append(c); i += 1
    return bytes(out)

def extract_text_from_content(content):
    out = []
    i = 0
    n = len(content)
    # naive tokenizer for text operators
    while i < n:
        c = content[i]
        if c == 0x28:  # (
            j = i+1
            depth = 1
            buf = bytearray()
            while j < n:
                ch = content[j]
                if ch == 0x5c:
                    buf.append(ch)
                    if j+1 < n:
                        buf.append(content[j+1])
                    j += 2
                    continue
                if ch == 0x28:
                    depth += 1
                    buf.append(ch)
                elif ch == 0x29:
                    depth -= 1
                    if depth == 0:
                        break
                    buf.append(ch)
                else:
                    buf.append(ch)
                j += 1
            txt = unescape_pdf_literal(bytes(buf))
            out.append(txt.decode('latin-1', 'replace'))
            i = j+1
            continue
        if c == 0x5b:  # [ ... ] TJ array
            i += 1
            continue
        i += 1
    return ''.join(out)

def extract(path):
    data = load(path)
    objs = objects(data)
    texts = []
    for num, body in objs.items():
        if b'stream' in body:
            s = stream_bytes(body)
            if not s:
                continue
            if b'BT' in s or b'Tj' in s or b'TJ' in s:
                t = extract_text_from_content(s)
                if t.strip():
                    texts.append((num, t))
    # content streams reference order may be by object number; try page order via /Contents
    ordered = []
    page_refs = []
    for num, body in objs.items():
        if re.search(rb'/Type\s*/Page\b', body):
            cm = re.search(rb'/Contents\s+(\d+)\s+\d+\s+R', body)
            if cm:
                page_refs.append((num, int(cm.group(1))))
            else:
                carr = re.search(rb'/Contents\s*\[([^\]]*)\]', body)
                if carr:
                    ids = [int(x) for x in re.findall(rb'(\d+)\s+\d+\s+R', carr.group(1))]
                    page_refs.append((num, ids))
    seen = set()
    for _, cid in page_refs:
        ids = cid if isinstance(cid, list) else [cid]
        for oid in ids:
            if oid in seen: continue
            seen.add(oid)
            body = objs.get(oid)
            if not body: continue
            s = stream_bytes(body)
            if s:
                ordered.append(extract_text_from_content(s))
    if not ordered:
        ordered = [t for _, t in sorted(texts)]
    return '\n'.join(ordered)

if __name__ == '__main__':
    print(extract(sys.argv[1]))

import re, sys, zlib

def get_objects(d):
    objs = {}
    for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj\b', d):
        start = m.end()
        end = d.find(b'endobj', start)
        if end == -1:
            continue
        objs[int(m.group(1))] = d[start:end]
    return objs

def stream_of(body):
    m = re.search(rb'stream\r?\n', body)
    if not m:
        return None
    s = m.end()
    e = body.rfind(b'endstream')
    raw = body[s:e]
    if raw.endswith(b'\n'): raw = raw[:-1]
    if raw.endswith(b'\r'): raw = raw[:-1]
    if b'FlateDecode' in body[:m.start()]:
        try: return zlib.decompress(raw)
        except Exception:
            try: return zlib.decompressobj().decompress(raw)
            except Exception: return None
    return raw

def parse_cmap(data):
    m = {}
    for bf in re.finditer(rb'beginbfchar(.*?)endbfchar', data, re.S):
        for mm in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', bf.group(1)):
            src = int(mm.group(1), 16)
            dst = mm.group(2).decode()
            # dst is utf-16be hex
            try:
                txt = bytes.fromhex(dst).decode('utf-16-be', 'replace')
            except Exception:
                txt = ''
            m[src] = txt
    for bf in re.finditer(rb'beginbfrange(.*?)endbfrange', data, re.S):
        for mm in re.finditer(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', bf.group(1)):
            lo = int(mm.group(1),16); hi = int(mm.group(2),16); dst=int(mm.group(3),16)
            for i in range(hi-lo+1):
                try:
                    m[lo+i] = chr(dst+i)
                except Exception:
                    pass
    return m

def build_font_maps(d, objs):
    # map font resource name -> cmap dict, and code byte-length
    font_maps = {}
    for num, body in objs.items():
        if b'/Type0' in body or b'/Font' in body:
            tu = re.search(rb'/ToUnicode\s+(\d+)\s+\d+\s+R', body)
            # font resource name mapping comes from page resources; handle separately
    # Build per-font-object cmap
    font_cmap = {}
    for num, body in objs.items():
        if re.search(rb'/Type\s*/Font', body) or b'/ToUnicode' in body:
            tu = re.search(rb'/ToUnicode\s+(\d+)\s+\d+\s+R', body)
            if tu:
                tob = objs.get(int(tu.group(1)))
                if tob:
                    s = stream_of(tob)
                    if s:
                        font_cmap[num] = parse_cmap(s)
    # Map resource names (/F4 etc) to font object ids per page resources
    name_to_obj = {}
    for num, body in objs.items():
        for fm in re.finditer(rb'/Font\s*<<(.*?)>>', body, re.S):
            for rm in re.finditer(rb'/([A-Za-z0-9]+)\s+(\d+)\s+\d+\s+R', fm.group(1)):
                name_to_obj[rm.group(1).decode()] = int(rm.group(2))
    return font_cmap, name_to_obj

def decode_hex_string(hexstr, cmap, nbytes):
    out = []
    h = hexstr.decode()
    step = nbytes*2
    for i in range(0, len(h), step):
        code = int(h[i:i+step], 16)
        if code in cmap:
            out.append(cmap[code])
        else:
            try:
                out.append(chr(code))
            except Exception:
                pass
    return ''.join(out)

def extract_page_text(content, font_cmap, name_to_obj):
    out = []
    cur_cmap = {}
    cur_nbytes = 1
    i = 0; n = len(content)
    last_y = None
    while i < n:
        m = re.compile(rb'/([A-Za-z0-9]+)\s+[\d.]+\s+Tf').match(content, i)
        if m:
            name = m.group(1).decode()
            oid = name_to_obj.get(name)
            cur_cmap = font_cmap.get(oid, {})
            # determine byte length: if codes >255 use 2
            cur_nbytes = 2 if (cur_cmap and max(cur_cmap) > 255) else 1
            if not cur_cmap:
                cur_nbytes = 2 if b'Type0' in ' '.join([]) else 1
            i = m.end(); continue
        m = re.compile(rb'<([0-9A-Fa-f\s]+)>\s*Tj').match(content, i)
        if m:
            hx = re.sub(rb'\s', b'', m.group(1))
            out.append(decode_hex_string(hx, cur_cmap, cur_nbytes))
            i = m.end(); continue
        # Td/Tm to detect line breaks by y movement
        m = re.compile(rb'([\d.-]+)\s+0\s+Td').match(content, i)
        if m:
            i = m.end(); continue
        m = re.compile(rb'1 0 0 -1 ([\d.-]+) ([\d.-]+) Tm').match(content, i)
        if m:
            y = float(m.group(2))
            if last_y is not None and abs(y-last_y) > 1:
                out.append('\n')
            last_y = y
            i = m.end(); continue
        i += 1
    return ''.join(out)

def extract(path):
    d = open(path,'rb').read()
    objs = get_objects(d)
    font_cmap, name_to_obj = build_font_maps(d, objs)
    pages = []
    for num, body in objs.items():
        if re.search(rb'/Type\s*/Page\b', body):
            cs = []
            cm = re.search(rb'/Contents\s+(\d+)\s+\d+\s+R', body)
            if cm: cs = [int(cm.group(1))]
            else:
                carr = re.search(rb'/Contents\s*\[([^\]]*)\]', body)
                if carr: cs = [int(x) for x in re.findall(rb'(\d+)\s+\d+\s+R', carr.group(1))]
            pages.append((num, cs))
    pages.sort()
    out = []
    for num, cs in pages:
        for cid in cs:
            b = objs.get(cid)
            if not b: continue
            s = stream_of(b)
            if s:
                out.append(extract_page_text(s, font_cmap, name_to_obj))
    return '\n'.join(out)

if __name__ == '__main__':
    print(extract(sys.argv[1]))

